import{_ as o,o as d,c as a,a2 as t}from"./chunks/framework.BM5YPQmL.js";const v=JSON.parse('{"title":"Sound drivers","description":"","frontmatter":{},"headers":[],"relativePath":"l1/driver-snd.md","filePath":"l1/driver-snd.md"}'),r={name:"l1/driver-snd.md"};function i(s,e,c,n,l,h){return d(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="sound-drivers" tabindex="-1">Sound drivers <a class="header-anchor" href="#sound-drivers" aria-label="Permalink to &quot;Sound drivers&quot;">​</a></h1><p>How an audio family joins the sound service.</p><h2 id="the-model-3-0-0" tabindex="-1">The model (3.0.0) <a class="header-anchor" href="#the-model-3-0-0" aria-label="Permalink to &quot;The model (3.0.0)&quot;">​</a></h2><ul><li>Drivers live in <code>ocos/drivers/audio/</code> - one file per family: HDA (<code>drv_audio_hda.c</code>), AC&#39;97, SB16, ES1370, virtio-snd; USB audio hangs off the USB class drivers (<code>drv_usb_audio.c</code>).</li><li>Identity: <code>OC_DRIVER_DECL(&quot;snd&quot;, &quot;hda&quot;, &amp;g_snd_probe_hda, &quot;Intel HD Audio&quot;)</code> - same collector as every other class.</li><li>The device table + mixer + playback engine live in the sound service (<code>ocos/services/audio/</code>): device registry (<code>driver_snd_device_t</code>, name/channels/rate/volume), the tone synthesizer (<code>driver_snd_make_tone</code> - the 440 Hz test tone behind <code>play</code>), and the L1SVC category 4 surface.</li></ul><h2 id="the-service-surface-17-ops" tabindex="-1">The service surface (17 ops) <a class="header-anchor" href="#the-service-surface-17-ops" aria-label="Permalink to &quot;The service surface (17 ops)&quot;">​</a></h2><p><code>sound</code> (device overview), per-driver status (<code>hda</code>, <code>ac97</code>, <code>sb16</code>, <code>es1370</code>, <code>virtiosnd</code>, <code>usbaudio</code>), <code>play [device] [rate]</code> (the test tone), <code>volume [device] [0-100]</code>, and the selftest family (<code>hda_test</code> .. <code>sample_rate_test</code>, the RW loopback, the sample-rate accuracy probe).</p><h2 id="defensive-notes-carried-in-the-code" tabindex="-1">Defensive notes carried in the code <a class="header-anchor" href="#defensive-notes-carried-in-the-code" aria-label="Permalink to &quot;Defensive notes carried in the code&quot;">​</a></h2><ul><li>A card reporting <code>channels == 0</code> must not divide by zero in the frame-count line (BUG-0243: the service reports 0 frames and the play reports the device error honestly).</li><li>The <code>sound-tool</code> wizard validates the volume/rate numbers digits-only before they reach the service - keep that layering when adding fields.</li></ul><h2 id="what-a-new-family-looks-like" tabindex="-1">What a new family looks like <a class="header-anchor" href="#what-a-new-family-looks-like" aria-label="Permalink to &quot;What a new family looks like&quot;">​</a></h2><ol><li><code>ocos/drivers/audio/drv_audio_&lt;fam&gt;.{c,h}</code> - probe, descriptor parse, PCM stream setup.</li><li><code>OC_DRIVER_DECL(&quot;snd&quot;, &quot;&lt;fam&gt;&quot;, &amp;ops, &quot;description&quot;)</code>.</li><li>A status op (append-only numbering) + the <code>sound-tool</code> classic table row + the per-driver submenu entry.</li></ol><h2 id="the-consumer-contract" tabindex="-1">The consumer contract <a class="header-anchor" href="#the-consumer-contract" aria-label="Permalink to &quot;The consumer contract&quot;">​</a></h2><p><code>sound-tool sound</code> -&gt; <code>sys_l1svc(SND, SOUND, ...)</code>; wizards and scripts read the English device lines; <code>play</code>&#39;s usage (<code>play [device] [rate 4000-96000]</code>) is the stable spelling.</p>',12)])])}const p=o(r,[["render",i]]);export{v as __pageData,p as default};
